contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner, address actor) public {
        vm.assume(actor != address(0) && _owner != address(0));
        vm.prank(address(this));
        c.setOwner(actor);
        vm.prank(actor);
        bool success = c.setOwner(_owner);
        assertTrue(success);
    }
